#!/usr/bin/env python3
"""TASK-20260929-9030f8 (J5) -- Q1 part 1: field polynomials by DF-8 and normal elements.

Pure-Python GF(2)[t] arithmetic on ints (bit j = coefficient of t^j).
Irreducibility: Ben-Or form of the Rabin test (the card's rule), cross-checked by
Berlekamp-matrix nullity (own code) and by sympy's Poly(..., modulus=2).is_irreducible.
"""
import itertools
import json
import sys

import sympy


def deg(a):
    return a.bit_length() - 1


def clmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        b >>= 1
    return r


def pmod(a, f):
    df = deg(f)
    while deg(a) >= df:
        a ^= f << (deg(a) - df)
    return a


def mulmod(a, b, f):
    return pmod(clmul(a, b), f)


def sqrmod(a, f):
    return mulmod(a, a, f)


def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a


def pderiv(f):
    r = 0
    for i in range(1, deg(f) + 1):
        if (f >> i) & 1 and i % 2 == 1:
            r |= 1 << (i - 1)
    return r


def poly_str(f):
    terms = []
    for i in range(deg(f), -1, -1):
        if (f >> i) & 1:
            terms.append('1' if i == 0 else ('t' if i == 1 else 't^%d' % i))
    return ' + '.join(terms)


def ben_or_irreducible(f):
    """Ben-Or: f of degree n is irreducible iff gcd(f, t^(2^i) - t) = 1 for i = 1..floor(n/2)."""
    n = deg(f)
    if n < 1:
        return False
    x = pmod(2, f)
    u = x
    for _ in range(1, n // 2 + 1):
        u = sqrmod(u, f)
        if pgcd(f, u ^ x) != 1:
            return False
    return True


def gf2_rank(rows):
    piv = {}
    rank = 0
    for r in rows:
        while r:
            h = deg(r)
            if h in piv:
                r ^= piv[h]
            else:
                piv[h] = r
                rank += 1
                break
    return rank


def berlekamp_irreducible(f):
    """Square-free and nullity(Q - I) == 1 (number of distinct irreducible factors)."""
    n = deg(f)
    if n < 1:
        return False
    if pgcd(f, pderiv(f)) != 1:
        return False
    t2 = pmod(4, f)
    rows, cur = [], 1
    for i in range(n):
        rows.append(cur ^ (1 << i))
        cur = mulmod(cur, t2, f)
    return n - gf2_rank(rows) == 1


def sympy_irreducible(f):
    t = sympy.Symbol('t')
    coeffs = [(f >> i) & 1 for i in range(deg(f), -1, -1)]
    return bool(sympy.Poly.from_list(coeffs, t, modulus=2).is_irreducible)


def is_prime_small(p):
    if p < 2:
        return False
    d = 2
    while d * d <= p:
        if p % d == 0:
            return False
        d += 1
    return True


def mult_order(a, p):
    o, v = 1, a % p
    while v != 1:
        v = v * a % p
        o += 1
    return o


def type2_info(n):
    p = 2 * n + 1
    info = {'two_n_plus_1': p, 'two_n_plus_1_prime': is_prime_small(p)}
    if not info['two_n_plus_1_prime']:
        info['type_II_ONB_exists'] = False
        return info
    o = mult_order(2, p)
    info['ord_2_mod_2n_plus_1'] = o
    info['two_primitive'] = (o == 2 * n)
    info['p_mod_4'] = p % 4
    info['two_generates_QR_and_p_3mod4'] = (p % 4 == 3 and o == n)
    info['type_II_ONB_exists'] = info['two_primitive'] or info['two_generates_QR_and_p_3mod4']
    return info


def recurrence_poly(n):
    """f_0 = 1, f_1 = t + 1, f_(i+1) = t f_i + f_(i-1)."""
    if n == 0:
        return 1
    fm1, fi = 1, 3
    for _ in range(1, n):
        fm1, fi = fi, clmul(2, fi) ^ fm1
    return fi


def conjugates(v, f):
    n = deg(f)
    c = [pmod(v, f)]
    for _ in range(n - 1):
        c.append(sqrmod(c[-1], f))
    return c


def is_normal(v, f):
    return gf2_rank(conjugates(v, f)) == deg(f)


def gauss_jordan_coords(w, f):
    """Basis matrix Bm: column i = polynomial-basis vector of w^(2^i).
    Gauss-Jordan on [Bm | I] -> [I | Bm^-1].  Returns (conj, coordcol) with
    coordcol[j] = normal-basis coordinate vector of t^j (bit i = coefficient of w^(2^i))."""
    n = deg(f)
    conj = conjugates(w, f)
    rows = []
    for r in range(n):
        v = 0
        for c in range(n):
            if (conj[c] >> r) & 1:
                v |= 1 << c
        v |= 1 << (n + r)
        rows.append(v)
    for col in range(n):
        piv = next((r for r in range(col, n) if (rows[r] >> col) & 1), None)
        if piv is None:
            raise ValueError('basis matrix singular')
        rows[col], rows[piv] = rows[piv], rows[col]
        for r in range(n):
            if r != col and (rows[r] >> col) & 1:
                rows[r] ^= rows[col]
    inv_rows = [rows[r] >> n for r in range(n)]
    coordcol = []
    for j in range(n):
        v = 0
        for i in range(n):
            if (inv_rows[i] >> j) & 1:
                v |= 1 << i
        coordcol.append(v)
    # verification: reconstruct t^j from its coordinates
    for j in range(n):
        acc = 0
        for i in range(n):
            if (coordcol[j] >> i) & 1:
                acc ^= conj[i]
        assert acc == (1 << j), 'coordinate reconstruction failed'
    return conj, coordcol


def coords(x, coordcol):
    c, j = 0, 0
    while x:
        if x & 1:
            c ^= coordcol[j]
        x >>= 1
        j += 1
    return c


def rotl(c, s, n):
    s %= n
    return ((c << s) | (c >> (n - s))) & ((1 << n) - 1) if s else c


def mult_complexity(w, f):
    n = deg(f)
    conj, coordcol = gauss_jordan_coords(w, f)
    total = 0
    for i in range(n):
        total += bin(coords(mulmod(conj[0], conj[i], f), coordcol)).count('1')
    return total


def frobenius_shift_ok(f, coordcol):
    n = deg(f)
    for j in range(n):
        x = 1 << j
        if coords(sqrmod(x, f), coordcol) != rotl(coords(x, coordcol), 1, n):
            return False
    return True


def trace_mask(f):
    n = deg(f)
    m = 0
    for i in range(n):
        v = pmod(1 << i, f)
        acc = 0
        for _ in range(n):
            acc ^= v
            v = sqrmod(v, f)
        assert acc in (0, 1)
        m |= acc << i
    return m


def lowest_weight_irreducible(n, log):
    """Lowest weight first; within the weight, least as an integer.  Every
    candidate below the selected one (in that order) is checked reducible by
    Ben-Or AND by Berlekamp."""
    for W in range(2, n + 2):
        cands = sorted((1 << n) | sum(1 << e for e in combo)
                       for combo in itertools.combinations(range(n), W - 1))
        for f in cands:
            bo = ben_or_irreducible(f)
            bk = berlekamp_irreducible(f)
            if bo != bk:
                raise AssertionError('Ben-Or/Berlekamp disagree on %s' % poly_str(f))
            if bo:
                log.append('n=%d: weight %d is the lowest weight with an irreducible; '
                           'least such integer %d = %s (%d weight-%d candidates tested '
                           'before it, all reducible)' % (n, W, f, poly_str(f),
                                                         cands.index(f), W))
                return f, W, cands.index(f)
        log.append('n=%d: no irreducible polynomial of weight %d (%d candidates)'
                   % (n, W, len(cands)))
    raise AssertionError('unreachable')


def least_normal(f):
    v = 0
    while not is_normal(v, f):
        v += 1
    return v


NAMED = {17: (1 << 17) | (1 << 3) | 1,                       # t^17 + t^3 + 1 (CELL-K17, CELL-RC1)
         19: (1 << 19) | (1 << 5) | (1 << 2) | (1 << 1) | 1}  # t^19+t^5+t^2+t+1 (K19, O19)


def main():
    log = []
    out = {}
    for n in (13, 17, 19, 23, 41):
        rec = {'n': n}
        t2 = type2_info(n)
        rec['type_II'] = t2
        fn = recurrence_poly(n)
        fn_rec = {'poly_int': fn, 'poly_hex': hex(fn), 'poly': poly_str(fn),
                  'degree': deg(fn), 'weight': bin(fn).count('1'),
                  'irreducible_ben_or': ben_or_irreducible(fn),
                  'irreducible_berlekamp': berlekamp_irreducible(fn),
                  'irreducible_sympy': sympy_irreducible(fn)}
        if fn_rec['irreducible_ben_or']:
            fn_rec['t_normal'] = is_normal(2, fn)
            if fn_rec['t_normal']:
                fn_rec['mult_complexity_of_t_basis'] = mult_complexity(2, fn)
        rec['recurrence_f_n'] = fn_rec
        if n in NAMED:
            f = NAMED[n]
            rec['selection'] = 'named on the card (DF-8 first clause)'
            type2_accepted = False
        else:
            if t2['type_II_ONB_exists']:
                acc = (fn_rec['irreducible_ben_or'] and fn_rec.get('t_normal', False)
                       and fn_rec.get('mult_complexity_of_t_basis') == 2 * n - 1)
            else:
                acc = False
            type2_accepted = acc
            if acc:
                f = fn
                rec['selection'] = 'DF-8 type-II clause: f_n accepted (irreducible, t normal, complexity 2n-1)'
            else:
                f, W, idx = lowest_weight_irreducible(n, log)
                rec['selection'] = ('DF-8 fallback clause: lowest-weight irreducible, least as integer '
                                    '(type-II %s)' % ('ONB does not exist' if not t2['type_II_ONB_exists']
                                                     else 'f_n rejected'))
        rec['type_II_rule_accepted'] = type2_accepted
        # sensitivity: what the fallback clause would give at this n
        if n not in NAMED and type2_accepted:
            fb, W, idx = lowest_weight_irreducible(n, log)
            rec['fallback_if_type_II_rejected'] = {'poly_int': fb, 'poly_hex': hex(fb),
                                                    'poly': poly_str(fb), 'weight': W}
            if n <= 23:
                wfb = least_normal(fb)
                rec['fallback_if_type_II_rejected']['least_normal_element'] = wfb
        rec['field_poly_int'] = f
        rec['field_poly_hex'] = hex(f)
        rec['field_poly'] = poly_str(f)
        rec['field_poly_weight'] = bin(f).count('1')
        rec['field_poly_irreducible_ben_or'] = ben_or_irreducible(f)
        rec['field_poly_irreducible_berlekamp'] = berlekamp_irreducible(f)
        rec['field_poly_irreducible_sympy'] = sympy_irreducible(f)
        if type2_accepted:
            w = 2
            rec['normal_element_rule'] = 't (type-II rule accepted)'
        else:
            w = least_normal(f)
            rec['normal_element_rule'] = 'least integer whose n conjugates are F2-independent'
            # independent confirmation that all smaller integers are not normal
            rec['all_smaller_integers_not_normal'] = all(not is_normal(v, f) for v in range(w))
        rec['normal_element_w_int'] = w
        rec['normal_element_w_poly'] = poly_str(w) if w else '0'
        rec['w_is_normal'] = is_normal(w, f)
        conj, coordcol = gauss_jordan_coords(w, f)
        rec['coordinate_reconstruction_ok'] = True
        rec['frobenius_is_cyclic_shift_ok'] = frobenius_shift_ok(f, coordcol)
        rec['mult_complexity_of_w_basis'] = mult_complexity(w, f)
        rec['trace_mask_int'] = trace_mask(f)
        rec['trace_mask_bits'] = [i for i in range(n) if (rec['trace_mask_int'] >> i) & 1]
        rec['trace_of_w'] = bin(w & 0).count('1')  # placeholder overwritten below
        tw = 0
        v = pmod(w, f)
        for _ in range(n):
            tw ^= v
            v = sqrmod(v, f)
        rec['trace_of_w'] = tw
        rec['coordcol'] = coordcol
        out[str(n)] = rec
    out['log'] = log
    json.dump(out, open('fields.json', 'w'), indent=1)
    for n in ('13', '17', '19', '23', '41'):
        r = out[n]
        print('n=%s field=%s (%s) sel=[%s] typeII_exists=%s accepted=%s w=%d (%s) '
              'irr(BenOr/Berl/sympy)=%s/%s/%s complexity(w)=%d frob_shift=%s trace_mask_bits=%s'
              % (n, r['field_poly'], r['field_poly_hex'], r['selection'],
                 r['type_II']['type_II_ONB_exists'], r['type_II_rule_accepted'],
                 r['normal_element_w_int'], r['normal_element_w_poly'],
                 r['field_poly_irreducible_ben_or'], r['field_poly_irreducible_berlekamp'],
                 r['field_poly_irreducible_sympy'], r['mult_complexity_of_w_basis'],
                 r['frobenius_is_cyclic_shift_ok'], r['trace_mask_bits']))
        print('   type_II info:', json.dumps(r['type_II']))
        print('   recurrence f_n:', json.dumps(r['recurrence_f_n']))
        if 'fallback_if_type_II_rejected' in r:
            print('   fallback if type-II rejected:', json.dumps(r['fallback_if_type_II_rejected']))
    for line in log:
        print('LOG', line)


if __name__ == '__main__':
    main()

