/* TASK-20260929-9030f8 (J5) -- Q2 independent check pipeline, C (gcc).
 * Shares no code with q2_purity.py:
 *  - field arithmetic: polynomial basis, full carry-less product then reduction mod F,
 *    inversion by the extended Euclidean algorithm (no log/exp tables);
 *  - trace by its definition sum_i c^(2^i) (mask derived from it, cross-checked);
 *  - point count by enumeration over every x;
 *  - coset labels by a CYCLIC WALK: find G of order #E (checked against every prime
 *    divisor), visit i*G for i = 1..#E-1 by repeated addition, label = i mod 2 / i mod 4
 *    (valid because E is cyclic: i*G in 2^j E iff 2^j | i); walk must visit every affine
 *    point exactly once and close at i = #E;
 *  - trace criterion (P in 2E iff Tr(x) = Tr(A)) as a third label check;
 *  - normal-basis coordinates through the trace-DUAL basis theta: c_j(x) = Tr(x theta^(2^j)),
 *    theta solved by Gaussian elimination from Tr(w^(2^i) theta) = delta_i0; reconstruction
 *    and Frobenius-shift verified for every x;
 *  - F4 by direct lexicographic comparison of the n rotated sequences.
 * Usage: q2_check CELL n fhex A B w kob r1 [r2 [r3]]
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef uint64_t u64;
static int N;
static u64 F, CA, CB, Q;
static u64 TMASK;

static inline int pdeg(u64 a) { return a ? 63 - __builtin_clzll(a) : -1; }

static inline u64 gmul(u64 a, u64 b) {
    u64 r = 0;
    for (int i = 0; i < N; i++) if ((b >> i) & 1) r ^= a << i;
    for (int d = 2 * N - 2; d >= N; d--) if ((r >> d) & 1) r ^= F << (d - N);
    return r;
}
static inline u64 gsqr(u64 a) { return gmul(a, a); }
static u64 clmul_lo(u64 a, u64 b) { u64 r = 0; while (b) { if (b & 1) r ^= a; a <<= 1; b >>= 1; } return r; }
static u64 ginv(u64 a) {
    u64 r0 = F, r1 = a, s0 = 0, s1 = 1;
    while (r1) {
        u64 q = 0, r = r0; int d1 = pdeg(r1);
        while (r && pdeg(r) >= d1) { int sh = pdeg(r) - d1; q ^= 1ULL << sh; r ^= r1 << sh; }
        u64 s = s0 ^ clmul_lo(q, s1);
        r0 = r1; r1 = r; s0 = s1; s1 = s;
    }
    if (r0 != 1) { fprintf(stderr, "ginv: gcd != 1\n"); exit(2); }
    return s0;
}
static int tr_direct(u64 c) { u64 acc = 0, v = c; for (int i = 0; i < N; i++) { acc ^= v; v = gsqr(v); } if (acc > 1) { fprintf(stderr, "trace not in F2\n"); exit(2); } return (int)acc; }
static inline int tr(u64 c) { return __builtin_popcountll(c & TMASK) & 1; }
static u64 halftrace(u64 c) { u64 acc = 0, v = c; for (int i = 0; i <= (N - 1) / 2; i++) { acc ^= v; v = gsqr(gsqr(v)); } return acc; }

typedef struct { u64 x, y; int inf; } pt;
static pt ec_dbl(pt P) {
    pt R = {0, 0, 1};
    if (P.inf || P.x == 0) return R;
    u64 lam = P.x ^ gmul(P.y, ginv(P.x));
    R.x = gsqr(lam) ^ lam ^ CA;
    R.y = gsqr(P.x) ^ gmul(lam ^ 1, R.x);
    R.inf = 0;
    return R;
}
static pt ec_add(pt P, pt Qp) {
    if (P.inf) return Qp;
    if (Qp.inf) return P;
    if (P.x == Qp.x) { if (P.y == Qp.y) return ec_dbl(P); pt R = {0, 0, 1}; return R; }
    u64 lam = gmul(P.y ^ Qp.y, ginv(P.x ^ Qp.x));
    pt R;
    R.x = gsqr(lam) ^ lam ^ P.x ^ Qp.x ^ CA;
    R.y = gmul(lam, P.x ^ R.x) ^ R.x ^ P.y;
    R.inf = 0;
    return R;
}
static pt ec_mul(u64 k, pt P) { /* right-to-left binary */
    pt R = {0, 0, 1}, T = P;
    while (k) { if (k & 1) R = ec_add(R, T); T = ec_dbl(T); k >>= 1; }
    return R;
}
static int on_curve(pt P) {
    if (P.inf) return 1;
    u64 x = P.x, y = P.y, x2 = gsqr(x);
    return (gsqr(y) ^ gmul(x, y)) == (gmul(x2, x) ^ gmul(CA, x2) ^ CB);
}

/* rank of n vectors of n bits */
static int rank_vecs(const u64 *v, int n) {
    u64 a[64]; memcpy(a, v, sizeof(u64) * n);
    int rank = 0;
    for (int col = 0; col < n && rank < n; col++) {
        int piv = -1;
        for (int r = rank; r < n; r++) if ((a[r] >> col) & 1) { piv = r; break; }
        if (piv < 0) continue;
        u64 t = a[piv]; a[piv] = a[rank]; a[rank] = t;
        for (int r = 0; r < n; r++) if (r != rank && ((a[r] >> col) & 1)) a[r] ^= a[rank];
        rank++;
    }
    return rank;
}
static int is_normal(u64 v) {
    u64 c[64]; c[0] = v;
    for (int i = 1; i < N; i++) c[i] = gsqr(c[i - 1]);
    return rank_vecs(c, N) == N;
}

int main(int argc, char **argv) {
    if (argc < 9) { fprintf(stderr, "usage\n"); return 1; }
    const char *cell = argv[1];
    N = atoi(argv[2]); F = strtoull(argv[3], 0, 16); CA = strtoull(argv[4], 0, 10); CB = strtoull(argv[5], 0, 10);
    u64 W = strtoull(argv[6], 0, 10); int kob = atoi(argv[7]);
    int nr = argc - 8, rs[4];
    for (int i = 0; i < nr; i++) rs[i] = atoi(argv[8 + i]);
    Q = 1ULL << N;
    /* self-tests of field arithmetic */
    srand(12345);
    for (int k = 0; k < 20000; k++) {
        u64 a = ((((u64)rand()) << 31) ^ (u64)rand()) & (Q - 1); if (!a) continue;
        if (gmul(a, ginv(a)) != 1) { fprintf(stderr, "inverse self-test failed\n"); return 2; }
    }
    TMASK = 0;
    for (int i = 0; i < N; i++) TMASK |= ((u64)tr_direct(1ULL << i)) << i;
    for (int k = 0; k < 2000; k++) {
        u64 a = ((((u64)rand()) << 31) ^ (u64)rand()) & (Q - 1);
        if (tr(a) != tr_direct(a)) { fprintf(stderr, "trace self-test failed\n"); return 2; }
    }
    printf("{\"cell\":\"%s\",\"n\":%d,\"f\":\"0x%llx\",\"A\":%llu,\"B\":%llu,\"w\":%llu,\"tmask\":\"0x%llx\"", cell, N,
           (unsigned long long)F, (unsigned long long)CA, (unsigned long long)CB, (unsigned long long)W, (unsigned long long)TMASK);
    /* ---- point count */
    unsigned char *haspts = calloc(Q, 1);
    u64 NE = 2; /* infinity + (0, sqrt B) */
    haspts[0] = 1;
    for (u64 x = 1; x < Q; x++) {
        u64 c = x ^ CA ^ gmul(CB, gsqr(ginv(x)));
        if (!tr(c)) { haspts[x] = 2; NE += 2; }
    }
    printf(",\"order_by_count\":%llu", (unsigned long long)NE);
    /* ---- factor NE by trial division */
    u64 pr[32]; int np = 0; u64 m = NE;
    for (u64 d = 2; d * d <= m; d++) if (m % d == 0) { pr[np++] = d; while (m % d == 0) m /= d; }
    if (m > 1) pr[np++] = m;
    printf(",\"prime_divisors\":[");
    for (int i = 0; i < np; i++) printf("%s%llu", i ? "," : "", (unsigned long long)pr[i]);
    printf("]");
    /* ---- find generator G of order NE */
    pt G = {0, 0, 1}; int found = 0;
    for (u64 x = 1; x < Q && !found; x++) {
        if (haspts[x] != 2) continue;
        u64 c = x ^ CA ^ gmul(CB, gsqr(ginv(x)));
        u64 z = halftrace(c);
        if ((gsqr(z) ^ z) != c) { fprintf(stderr, "halftrace failed\n"); return 2; }
        pt P = {x, gmul(x, z), 0};
        if (!on_curve(P)) { fprintf(stderr, "not on curve\n"); return 2; }
        if (!ec_mul(NE, P).inf) { fprintf(stderr, "NE*P != O\n"); return 2; }
        int ok = 1;
        for (int i = 0; i < np; i++) if (ec_mul(NE / pr[i], P).inf) { ok = 0; break; }
        if (ok) { G = P; found = 1; }
    }
    if (!found) { printf(",\"cyclic\":false}\n"); return 3; }
    printf(",\"cyclic\":true,\"generator\":[%llu,%llu]", (unsigned long long)G.x, (unsigned long long)G.y);
    /* ---- walk */
    unsigned char *lab = malloc(2 * Q); memset(lab, 255, 2 * Q);
    pt R = G; u64 i = 1, visited = 0, dup = 0, offcurve = 0, trmismatch = 0;
    int trA = tr(CA);
    while (!R.inf) {
        if (!on_curve(R)) offcurve++;
        int slot = (R.x == 0) ? 0 : (R.y < (R.x ^ R.y) ? 0 : 1);
        u64 idx = 2 * R.x + slot;
        if (lab[idx] != 255) dup++;
        lab[idx] = (unsigned char)(i & 3);
        visited++;
        if (((i & 1) == 0) != (tr(R.x) == trA)) trmismatch++;
        R = ec_add(R, G); i++;
    }
    u64 slotmismatch = 0;
    for (u64 x = 0; x < Q; x++) {
        int v = (lab[2 * x] != 255) + (lab[2 * x + 1] != 255);
        if (v != haspts[x]) slotmismatch++;
    }
    printf(",\"walk_closes_at\":%llu,\"visited\":%llu,\"duplicates\":%llu,\"off_curve\":%llu,\"slot_mismatch\":%llu,\"trace_criterion_mismatch\":%llu",
           (unsigned long long)i, (unsigned long long)visited, (unsigned long long)dup, (unsigned long long)offcurve,
           (unsigned long long)slotmismatch, (unsigned long long)trmismatch);
    int four = (NE % 4 == 0);
    /* ---- normal element checks */
    int wnormal = is_normal(W), smaller_not_normal = 1;
    if (W != 2) for (u64 v = 0; v < W; v++) if (is_normal(v)) smaller_not_normal = 0;
    u64 conj[64]; conj[0] = W;
    for (int k = 1; k < N; k++) conj[k] = gsqr(conj[k - 1]);
    /* dual basis: solve sum_k T[i][k] theta_k = delta_{i0}, T[i][k] = Tr(w^(2^i) t^k) */
    u64 rows[64]; /* bits 0..N-1: coefficients over k; bit N: rhs */
    for (int r = 0; r < N; r++) {
        u64 v = 0;
        for (int k = 0; k < N; k++) if (tr(gmul(conj[r], 1ULL << k))) v |= 1ULL << k;
        if (r == 0) v |= 1ULL << N;
        rows[r] = v;
    }
    int prow = 0, pivcol[64];
    for (int col = 0; col < N; col++) {
        int piv = -1;
        for (int r = prow; r < N; r++) if ((rows[r] >> col) & 1) { piv = r; break; }
        if (piv < 0) { fprintf(stderr, "dual system singular\n"); return 2; }
        u64 t = rows[piv]; rows[piv] = rows[prow]; rows[prow] = t;
        for (int r = prow + 1; r < N; r++) if ((rows[r] >> col) & 1) rows[r] ^= rows[prow];
        pivcol[prow] = col; prow++;
    }
    u64 theta = 0; /* back substitution */
    for (int r = N - 1; r >= 0; r--) {
        int col = pivcol[r];
        int b = (int)((rows[r] >> N) & 1);
        for (int k = col + 1; k < N; k++) if ((rows[r] >> k) & 1) b ^= (int)((theta >> k) & 1);
        if (b) theta |= 1ULL << col;
    }
    u64 thc[64]; thc[0] = theta;
    for (int k = 1; k < N; k++) thc[k] = gsqr(thc[k - 1]);
    u64 coordcol[64];
    for (int k = 0; k < N; k++) {
        u64 v = 0;
        for (int j = 0; j < N; j++) if (tr(gmul(1ULL << k, thc[j]))) v |= 1ULL << j;
        coordcol[k] = v;
    }
    /* complexity of the w-basis */
    int complexity = 0;
    for (int k = 0; k < N; k++) {
        u64 p = gmul(conj[0], conj[k]), c = 0;
        for (int j = 0; j < N; j++) if ((p >> j) & 1) c ^= coordcol[j];
        complexity += __builtin_popcountll(c);
    }
    u64 *cx = malloc(sizeof(u64) * Q);
    u64 recbad = 0, frobbad = 0, nm = Q - 1 > 0 ? ((1ULL << N) - 1) : 0;
    for (u64 x = 0; x < Q; x++) {
        u64 c = 0;
        for (int j = 0; j < N; j++) if ((x >> j) & 1) c ^= coordcol[j];
        cx[x] = c;
        u64 rec = 0;
        for (int j = 0; j < N; j++) if ((c >> j) & 1) rec ^= conj[j];
        if (rec != x) recbad++;
    }
    for (u64 x = 0; x < Q; x++) {
        u64 c2 = cx[gsqr(x)], c = cx[x];
        if (c2 != (((c << 1) | (c >> (N - 1))) & nm)) frobbad++;
    }
    printf(",\"w_normal\":%d,\"all_smaller_not_normal\":%d,\"theta\":%llu,\"w_basis_complexity\":%d,\"reconstruction_failures\":%llu,\"frobenius_failures\":%llu",
           wnormal, (W != 2) ? smaller_not_normal : -1, (unsigned long long)theta, complexity, (unsigned long long)recbad, (unsigned long long)frobbad);
    /* ---- binomials for F1 */
    u64 C[64][64]; memset(C, 0, sizeof C);
    for (int a = 0; a <= N; a++) { C[a][0] = 1; for (int b = 1; b <= a; b++) C[a][b] = C[a - 1][b - 1] + (b <= a - 1 ? C[a - 1][b] : 0); }
    /* ---- rows */
    int nrows = 0; int fam[64], off[64], rr[64];
    for (int t = 0; t < nr; t++) {
        int r = rs[t], o3[3] = {0, (N - r) / 2, N - r};
        if (kob) { fam[nrows] = 1; off[nrows] = -1; rr[nrows++] = r; }
        for (int k = 0; k < 3; k++) { fam[nrows] = 2; off[nrows] = o3[k]; rr[nrows++] = r; }
        for (int k = 0; k < 3; k++) { fam[nrows] = 3; off[nrows] = o3[k]; rr[nrows++] = r; }
        if (kob) { fam[nrows] = 4; off[nrows] = -1; rr[nrows++] = r; }
    }
    u64 cnt[64][128]; unsigned m2[64][128], m4[64][128];
    memset(cnt, 0, sizeof cnt); memset(m2, 0, sizeof m2); memset(m4, 0, sizeof m4);
    int f1cls[8][64];
    for (int t = 0; t < nr; t++) {
        u64 M = 1ULL << rs[t], cum = 0;
        for (int w = 0; w <= N; w++) { f1cls[t][w] = (int)((M * (2 * cum + C[N][w])) >> (N + 1)); cum += C[N][w]; }
    }
    for (u64 x = 0; x < Q; x++) {
        if (!haspts[x]) continue;
        u64 c = cx[x];
        int wt = __builtin_popcountll(c);
        /* lexicographically least rotation, sequence s_i = c_{(i+s) mod N}, compared from i = 0 */
        int best = 0;
        for (int s = 1; s < N; s++) {
            for (int k = 0; k < N; k++) {
                int a = (int)((c >> ((k + s) % N)) & 1), b = (int)((c >> ((k + best) % N)) & 1);
                if (a != b) { if (a < b) best = s; break; }
            }
        }
        for (int q = 0; q < nrows; q++) {
            int r = rr[q]; u64 M = 1ULL << r; u64 h;
            if (fam[q] == 1) { int t = 0; while (rs[t] != r) t++; h = (u64)f1cls[t][wt]; }
            else if (fam[q] == 2) h = (c >> off[q]) & (M - 1);
            else if (fam[q] == 3) h = (x >> off[q]) & (M - 1);
            else { h = 0; for (int k = 0; k < r; k++) h = (h << 1) | ((c >> ((k + best) % N)) & 1); }
            for (int s = 0; s < 2; s++) {
                unsigned char l = lab[2 * x + s];
                if (l == 255) continue;
                cnt[q][h]++; m2[q][h] |= 1u << (l & 1); m4[q][h] |= 1u << (l & 3);
            }
        }
    }
    printf(",\"rows\":[");
    for (int q = 0; q < nrows; q++) {
        u64 M = 1ULL << rr[q], p2 = 0, p4 = 0; int ne = 0;
        for (u64 h = 0; h < M; h++) {
            if (!cnt[q][h]) continue;
            ne++;
            if (__builtin_popcount(m2[q][h]) == 1) p2 += cnt[q][h];
            if (__builtin_popcount(m4[q][h]) == 1) p4 += cnt[q][h];
        }
        printf("%s{\"family\":\"F%d\",\"offset\":%d,\"M\":%llu,\"nonempty\":%d,\"pure2\":%llu", q ? "," : "", fam[q], off[q],
               (unsigned long long)M, ne, (unsigned long long)p2);
        if (four && kob) printf(",\"pure4\":%llu", (unsigned long long)p4);
        printf("}");
    }
    printf("]}\n");
    return 0;
}

